<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ config('app.name', 'Notes') }}</title><style>body{margin:0;background:#f6f7fb;color:#1f2937;font-family:system-ui,sans-serif}nav{background:#111827;color:#fff}.nav,main{max-width:760px;margin:auto;padding:1rem}.nav,.actions{display:flex;gap:1rem;align-items:center;justify-content:space-between;flex-wrap:wrap}nav a{color:#fff}a{color:#2563eb}.card{background:#fff;margin:1rem 0;padding:1.25rem;border-radius:.5rem;box-shadow:0 1px 3px #0002}form,label{display:grid;gap:.7rem}input,textarea{box-sizing:border-box;width:100%;padding:.6rem;font:inherit}textarea{min-height:12rem}button,.button{padding:.6rem .9rem;border:0;border-radius:.25rem;background:#2563eb;color:#fff;text-decoration:none;font:inherit}.danger{background:#b91c1c}.status{padding:.75rem;color:#166534;background:#dcfce7}.errors{color:#b91c1c}</style></head><body><nav><div class="nav"><a href="{{ auth()->check() ? route('notes.index') : route('login') }}">Notes</a><div class="actions">@auth <span>{{ auth()->user()->name }}</span><form action="{{ route('logout') }}" method="POST">@csrf <button>Log out</button></form>@else <a href="{{ route('login') }}">Log in</a><a href="{{ route('register') }}">Register</a>@endauth</div></div></nav><main>@if(session('status'))<p class="status">{{ session('status') }}</p>@endif @yield('content')</main></body></html>